const BETA_WS_NAME = 'Working Study Timer Dashboard';
function beta_ws_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
function beta_ws_err(string $e): string { error_log('beta working-or-study: ' . $e); return 'Could not save. Try again.'; }
