// One short socket session for one or more events. code and channel_code both
// set: timer events read code, task events read either.
function beta_ws_send(string $key, array $events): bool {
    if ($key === '' || !$events) return false;
    $sid = beta_cc_open($key, BETA_WS_NAME);
    if ($sid === null) return false;
    $ok = true;
    foreach ($events as [$ev, $data]) $ok = beta_cc_req(beta_cc_url($sid), beta_cc_packet($key, $ev, ['channel_code' => $key] + $data))[0] === 200 && $ok;
    beta_cc_req(beta_cc_url($sid), '41');
    return $ok;
}
// Sends $events (if any), then asks the overlay for its state and reads the
// answer for at most ~2.5 s before closing. Never more than one poll in flight.
function beta_ws_status(string $key, array $events = []): array {
    $out = ['sent' => false, 'overlay' => false, 'state' => null, 'timer' => null, 'stats' => null];
    if ($key === '') return $out;
    $sid = beta_cc_open($key, BETA_WS_NAME);
    if ($sid === null) return $out;
    $ok = true;
    foreach ($events as [$ev, $data]) $ok = beta_cc_req(beta_cc_url($sid), beta_cc_packet($key, $ev, $data))[0] === 200 && $ok;
    $out['sent'] = $ok;
    if ($events) usleep(300000); // let the overlay apply the command before asking
    beta_cc_req(beta_cc_url($sid), beta_cc_packet($key, 'SPECTER_STATS_REQUEST', []));
    $end = microtime(true) + 2.5;
    while (($left = $end - microtime(true)) > 0.2 && ($out['timer'] === null || $out['stats'] === null)) {
        [$c, $got] = beta_cc_req(beta_cc_url($sid), null, max(1, (int) ceil($left)));
        if ($c !== 200 || $got === null) break;
        foreach (explode("\x1e", $got) as $p) {
            if ($p === '2') { beta_cc_req(beta_cc_url($sid), '3'); continue; }
            if (strpos($p, '42') !== 0) continue;
            $j = json_decode(substr($p, 2), true);
            if (!is_array($j) || !isset($j[0])) continue;
            $d = is_array($j[1] ?? null) ? $j[1] : [];
            unset($d['code'], $d['channel_code']);
            if ($j[0] === 'SPECTER_TIMER_STATE') { $out['state'] = (string) ($d['state'] ?? ''); $out['overlay'] = true; }
            elseif ($j[0] === 'SPECTER_TIMER_UPDATE') { $out['timer'] = $d; $out['overlay'] = true; }
            elseif ($j[0] === 'SPECTER_SESSION_STATS') { $out['stats'] = $d; $out['overlay'] = true; }
        }
    }
    beta_cc_req(beta_cc_url($sid), '41');
    return $out;
}
