        if ($ok) beta_ws_send((string) $api_key, [['TASK_UPDATE', ['owner' => 'streamer', 'task' => ['id' => $id, 'title' => $title, 'description' => $desc, 'category' => $cat, 'reward_points' => $pts, 'project' => $project, 'status' => $status, 'owner' => 'streamer']]]]);
        echo json_encode(['success' => $ok]);
        exit;
    }
    if ($action === 'ch_delete_streamer_task') {
        $id = intval($_POST['id'] ?? 0);
        if (!$id) { echo json_encode(['success' => false, 'error' => 'Missing id']); exit; }
        $stmt = $db->prepare("DELETE FROM streamer_tasks WHERE id=?");
        $stmt->bind_param("i", $id); $ok = $stmt->execute(); $stmt->close();
        if ($ok) beta_ws_send((string) $api_key, [['TASK_DELETE', ['task_id' => $id, 'owner' => 'streamer']]]);
        echo json_encode(['success' => $ok]);
        exit;
    }
    if ($action === 'ch_approve_user_task') {
        $id = intval($_POST['id'] ?? 0);
        if (!$id) { echo json_encode(['success' => false, 'error' => 'Missing id']); exit; }
        $db->begin_transaction();
        try {
            $stmt = $db->prepare("UPDATE user_tasks SET approval_status='approved' WHERE id=?");
            if (!$stmt) { throw new Exception('Prepare failed: ' . $db->error); }
            $stmt->bind_param("i", $id);
            $ok = $stmt->execute();
            $stmt->close();
            $rs = $db->prepare("SELECT id, user_id, user_name, title, reward_points, approval_status, status FROM user_tasks WHERE id=?");
            if (!$rs) { throw new Exception('Prepare failed: ' . $db->error); }
            $rs->bind_param("i", $id);
            if (!$rs->execute()) { throw new Exception('Execute failed: ' . $rs->error); }
            $task = $rs->get_result()->fetch_assoc();
            $rs->close();
            $awardResult = ['awarded' => false, 'points_awarded' => 0, 'new_total' => null];
            if ($ok && $task && (($task['status'] ?? '') === 'completed')) {
                $awardResult = $awardTaskPoints($id, $task, true);
            }
            $db->commit();
            if ($ok && $task) beta_ws_send((string) $api_key, array_merge([['TASK_APPROVE', ['task_id' => $task['id'], 'user_id' => $task['user_id'], 'user_name' => $task['user_name'], 'title' => $task['title'], 'reward_points' => $awardResult['awarded'] ? $awardResult['points_awarded'] : 0]]], ($awardResult['awarded'] ? [['TASK_REWARD_CONFIRM', ['task_id' => $task['id'], 'user_id' => $task['user_id'], 'user_name' => $task['user_name'], 'points_awarded' => $awardResult['points_awarded'], 'new_total' => $awardResult['new_total']]]] : [])));
            echo json_encode(['success' => $ok, 'task' => $task, 'reward' => $awardResult]);
        } catch (Exception $e) {
            $db->rollback();
            echo json_encode(['success' => false, 'error' => beta_ws_err($e->getMessage())]);
        }
        exit;
    }
    if ($action === 'ch_reject_user_task') {
        $id = intval($_POST['id'] ?? 0);
        if (!$id) { echo json_encode(['success' => false, 'error' => 'Missing id']); exit; }
        $stmt = $db->prepare("UPDATE user_tasks SET approval_status='rejected', status='rejected' WHERE id=?");
        $stmt->bind_param("i", $id); $ok = $stmt->execute(); $stmt->close();
        if ($ok) beta_ws_send((string) $api_key, [['TASK_REJECT', ['task_id' => $id]]]);
        echo json_encode(['success' => $ok]);
        exit;
    }
    if ($action === 'ch_complete_user_task') {
        $id = intval($_POST['id'] ?? 0);
        if (!$id) { echo json_encode(['success' => false, 'error' => 'Missing id']); exit; }
        $db->begin_transaction();
        try {
            $stmt = $db->prepare("UPDATE user_tasks SET status='completed', completed_at=NOW() WHERE id=?");
            if (!$stmt) { throw new Exception('Prepare failed: ' . $db->error); }
            $stmt->bind_param("i", $id);
            $ok = $stmt->execute();
            $stmt->close();
            $rs = $db->prepare("SELECT id, user_id, user_name, title, reward_points, approval_status, status FROM user_tasks WHERE id=?");
            if (!$rs) { throw new Exception('Prepare failed: ' . $db->error); }
            $rs->bind_param("i", $id);
            if (!$rs->execute()) { throw new Exception('Execute failed: ' . $rs->error); }
            $task = $rs->get_result()->fetch_assoc();
            $rs->close();
            $awardResult = ['awarded' => false, 'points_awarded' => 0, 'new_total' => null];
            if ($ok && $task) {
                $awardResult = $awardTaskPoints($id, $task);
            }
            $db->commit();
            if ($ok && $task) beta_ws_send((string) $api_key, array_merge([['TASK_COMPLETE', ['task_id' => $task['id'], 'user_id' => $task['user_id'], 'user_name' => $task['user_name'], 'title' => $task['title'], 'reward_points' => $awardResult['awarded'] ? $awardResult['points_awarded'] : 0, 'require_approval' => beta_ws_require_approval($db), 'owner' => 'user']]], ($awardResult['awarded'] ? [['TASK_REWARD_CONFIRM', ['task_id' => $task['id'], 'user_id' => $task['user_id'], 'user_name' => $task['user_name'], 'points_awarded' => $awardResult['points_awarded'], 'new_total' => $awardResult['new_total']]]] : [])));
            echo json_encode(['success' => $ok, 'task' => $task, 'reward' => $awardResult]);
        } catch (Exception $e) {
            $db->rollback();
            echo json_encode(['success' => false, 'error' => beta_ws_err($e->getMessage())]);
        }
        exit;
    }
    if ($action === 'ch_complete_streamer_task') {
        $id = intval($_POST['id'] ?? 0);
        if (!$id) { echo json_encode(['success' => false, 'error' => 'Missing id']); exit; }
        $stmt = $db->prepare("UPDATE streamer_tasks SET status='completed', completed_at=CURRENT_TIMESTAMP WHERE id=?");
        $stmt->bind_param("i", $id); $ok = $stmt->execute(); $stmt->close();
        if ($ok) beta_ws_send((string) $api_key, [['TASK_COMPLETE', ['task_id' => $id, 'owner' => 'streamer']]]);
        echo json_encode(['success' => $ok]);
        exit;
    }
    $taskCommands = ['task', 'done', 'rename', 'remove', 'mytasks', 'now', 'later', 'soon', 'backlog', 'project', 'projects', 'personaltimer', 'checktimer', 'timerhelp', 'studytimer', 'studyhelp'];
    if ($action === 'wcmd_get_command_status') {
        $statuses = [];
        foreach ($taskCommands as $cmd) { $statuses[$cmd] = 'Enabled'; }
        $placeholders = implode(',', array_fill(0, count($taskCommands), '?'));
        $stmt = $db->prepare("SELECT command, status FROM builtin_commands WHERE command IN ($placeholders)");
        if ($stmt) {
            $stmt->bind_param(str_repeat('s', count($taskCommands)), ...$taskCommands);
            if ($stmt->execute()) {
                $res = $stmt->get_result();
                while ($row = $res->fetch_assoc()) {
                    $statuses[$row['command']] = ($row['status'] === 'Disabled') ? 'Disabled' : 'Enabled';
                }
            }
            $stmt->close();
        }
        echo json_encode(['success' => true, 'data' => $statuses]);
        exit;
    }
    if ($action === 'wcmd_save_command_status') {
        $command = trim($_POST['command'] ?? '');
        if (!in_array($command, $taskCommands, true)) {
            echo json_encode(['success' => false, 'error' => 'Unknown command']);
            exit;
        }
        $status = (!empty($_POST['enabled']) && $_POST['enabled'] !== '0') ? 'Enabled' : 'Disabled';
        $stmt = $db->prepare("UPDATE builtin_commands SET status = ? WHERE command = ?");
        if (!$stmt) { echo json_encode(['success' => false, 'error' => beta_ws_err($db->error)]); exit; }
        $stmt->bind_param("ss", $status, $command);
        $ok = $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => $ok, 'command' => $command, 'status' => $status]);
        exit;
    }
    echo json_encode(['success' => false, 'error' => 'Unknown action']);
    exit;
}

// Load initial settings for page initialization
$initialSettings = ['focus_minutes' => 60, 'micro_break_minutes' => 5, 'recharge_break_minutes' => 30, 'reward_enabled' => 0, 'reward_points_per_task' => 10, 'cycle_count' => 4, 'show_cycle_badge' => 0, 'auto_cycle_enabled' => 0, 'theme' => 'dark', 'list_view_mode' => 'split'];
if ($db) {
    $stmt = $db->prepare("SELECT focus_minutes, micro_break_minutes, recharge_break_minutes, reward_enabled, reward_points_per_task, cycle_count, show_cycle_badge, auto_cycle_enabled, theme, list_view_mode FROM working_study_overlay_settings LIMIT 1");
    if ($stmt) {
        $stmt->execute();
        $result = $stmt->get_result();
        if ($row = $result->fetch_assoc()) {
            $initialSettings = $row;
        }
        $stmt->close();
    }
}

// Load initial task system settings
$chInitialSettings = ['require_approval' => 0, 'default_reward_points' => 50, 'allow_user_tasks' => 1, 'task_visible_overlay' => 1];
if ($db) {
    $stmt = $db->prepare("SELECT require_approval, default_reward_points, allow_user_tasks, task_visible_overlay FROM task_settings LIMIT 1");
    if ($stmt) {
        $stmt->execute();
        $row = $stmt->get_result()->fetch_assoc();
        if ($row) { $chInitialSettings = $row; }
        $stmt->close();
    }
}

$taskCommandList = ['task', 'done', 'rename', 'remove', 'mytasks', 'now', 'later', 'soon', 'backlog', 'project', 'projects', 'personaltimer', 'checktimer', 'timerhelp', 'studytimer', 'studyhelp'];
$taskCommandStatuses = array_fill_keys($taskCommandList, 'Enabled');
if ($db) {
    $placeholders = implode(',', array_fill(0, count($taskCommandList), '?'));
    $stmt = $db->prepare("SELECT command, status FROM builtin_commands WHERE command IN ($placeholders)");
    if ($stmt) {
        $stmt->bind_param(str_repeat('s', count($taskCommandList)), ...$taskCommandList);
        if ($stmt->execute()) {
            $res = $stmt->get_result();
            while ($row = $res->fetch_assoc()) {
                $taskCommandStatuses[$row['command']] = ($row['status'] === 'Disabled') ? 'Disabled' : 'Enabled';
            }
        }
        $stmt->close();
    }
}

header('Content-Type: application/json');
header('Cache-Control: no-store');
$bBase = 'https://overlay.botofthespecter.com/working-or-study.php?code=' . rawurlencode((string) $api_key);
if (($_GET['beta'] ?? '') === 'url') {
    if ((string) $api_key === '') beta_ws_fail('Your account has no channel key yet.', 409);
    $u = ['timer' => $overlayLinkWithCode, 'tasks' => $bBase . '&tasklist', 'streamer' => $bBase . '&tasklist&streamer=true', 'viewers' => $bBase . '&tasklist&streamer=false'][(string) ($_GET['kind'] ?? '')] ?? null;
    if ($u === null) beta_ws_fail('Unknown link.');
    echo json_encode(['success' => true, 'url' => $u]); exit();
}
$bS = [];
foreach (['focus_minutes', 'micro_break_minutes', 'recharge_break_minutes', 'cycle_count', 'show_cycle_badge', 'auto_cycle_enabled'] as $k) $bS[$k] = (int) ($initialSettings[$k] ?? 0);
$bS['theme'] = (string) ($initialSettings['theme'] ?? 'dark'); $bS['list_view_mode'] = (string) ($initialSettings['list_view_mode'] ?? 'split');
$bT = [];
foreach (['require_approval', 'default_reward_points', 'allow_user_tasks', 'task_visible_overlay'] as $k) $bT[$k] = (int) ($chInitialSettings[$k] ?? 0);
$bC = [];
foreach ($taskCommandStatuses as $k => $v) $bC[$k] = $v === 'Enabled' ? 1 : 0;
echo json_encode(['success' => true, 'has_key' => (string) $api_key !== '', 'settings' => $bS, 'task_settings' => $bT, 'commands' => $bC], JSON_UNESCAPED_UNICODE);
exit();
